from heapq import heappush, heappop

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    visited = [[False for _ in range(N)] for _ in range(N)]
    heap = []

    # Push all possible starting positions
    for i in range(N):
        for j in range(N):
            heappush(heap, (grid[i][j], [i, j]))

    while heap:
        _, (x, y) = heappop(heap)
        if visited[x][y]:
            continue
        visited[x][y] = True

        if k == 1:
            return [grid[x][y]]

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and not visited[nx][ny]:
                heappush(heap, (grid[nx][ny], [nx, ny]))
                visited[nx][ny] = True
                if k == 2:
                    return [grid[x][y], grid[nx][ny]]
                k -= 1

    return []
```

